    public CppString to_cooperative_matrix_component(uint id, CppString index)
    {
        if (unchecked((int)expression_type(id).op) != unchecked((int)Spv.Op.OpTypeCooperativeMatrixKHR))
        {
            return to_enclosed_unpacked_expression(id, true);
        }
        return Std.join(to_enclosed_unpacked_expression(id, true), ".thread_elements()[", index, "]");
    }
    public void emit_cooperative_matrix_unary_op(uint result_type, uint result_id, uint op0, string op)
    {
        emit_uninitialized_temporary_expression(result_type, result_id);
        {
            for (uint i = 0u; i < Globals.k_cooperative_matrix_components_per_thread; i++)
            {
                var index = Std.join(i, "u");
                statement(to_cooperative_matrix_component(result_id, index), " = ", op, to_cooperative_matrix_component(op0, index), ";");
            }
        }
        inherit_expression_dependencies(result_id, op0);
    }
    public void emit_cooperative_matrix_binary_op(uint result_type, uint result_id, uint op0, uint op1, string op)
    {
        emit_uninitialized_temporary_expression(result_type, result_id);
        {
            for (uint i = 0u; i < Globals.k_cooperative_matrix_components_per_thread; i++)
            {
                var index = Std.join(i, "u");
                statement(to_cooperative_matrix_component(result_id, index), " = ", to_cooperative_matrix_component(op0, index), " ", op, " ", to_cooperative_matrix_component(op1, index), ";");
            }
        }
        inherit_expression_dependencies(result_id, op0);
        inherit_expression_dependencies(result_id, op1);
    }
    public void emit_cooperative_matrix_unary_func_op(uint result_type, uint result_id, uint op0, string op)
    {
        emit_uninitialized_temporary_expression(result_type, result_id);
        {
            for (uint i = 0u; i < Globals.k_cooperative_matrix_components_per_thread; i++)
            {
                var index = Std.join(i, "u");
                statement(to_cooperative_matrix_component(result_id, index), " = ", op, "(", to_cooperative_matrix_component(op0, index), ");");
            }
        }
        inherit_expression_dependencies(result_id, op0);
    }
    public void emit_cooperative_matrix_select_op(uint result_type, uint result_id, uint cond, uint op0, uint op1)
    {
        emit_uninitialized_temporary_expression(result_type, result_id);
        {
            for (uint i = 0u; i < Globals.k_cooperative_matrix_components_per_thread; i++)
            {
                var index = Std.join(i, "u");
                statement(to_cooperative_matrix_component(result_id, index), " = ", to_enclosed_unpacked_expression(cond, true), " ? ", to_cooperative_matrix_component(op0, index), " : ", to_cooperative_matrix_component(op1, index), ";");
            }
        }
        inherit_expression_dependencies(result_id, cond);
        inherit_expression_dependencies(result_id, op0);
        inherit_expression_dependencies(result_id, op1);
    }
    public bool maybe_emit_cooperative_matrix_op(Instruction instruction)
    {
        if (instruction.length < 3u)
        {
            return false;
        }
        var opcode = unchecked((Spv.Op)instruction.op);
        bool has_result = false;
        bool has_result_type = false;
        Spv.Globals.HasResultAndType(opcode, Ptr.Ref<bool>(() => has_result, __v => has_result = __v), Ptr.Ref<bool>(() => has_result_type, __v => has_result_type = __v));
        if (!has_result_type)
        {
            return false;
        }
        var ops = stream(instruction);
        uint result_type = ops[0];
        uint result_id = ops[1];
        var type = get__SPIRType(result_type);
        while (type != null && (is_pointer(type) || is_array(type)))
        {
            type = maybe_get__SPIRType(((uint)type.parent_type));
        }
        if (!(type != null) || unchecked((int)type.op) != unchecked((int)Spv.Op.OpTypeCooperativeMatrixKHR))
        {
            if ((unchecked((int)opcode) == unchecked((int)Spv.Op.OpCompositeExtract) || unchecked((int)opcode) == unchecked((int)Spv.Op.OpVectorExtractDynamic)) && instruction.length >= 4u && unchecked((int)expression_type(ops[2]).op) == unchecked((int)Spv.Op.OpTypeCooperativeMatrixKHR))
            {
                bool index_is_id = unchecked((int)opcode) == unchecked((int)Spv.Op.OpVectorExtractDynamic);
                var index = index_is_id ? to_expression(ops[3], true) : Std.join(ops[3], "u");
                emit_op(result_type, result_id, to_cooperative_matrix_component(ops[2], index), should_forward(ops[2]), false);
                inherit_expression_dependencies(result_id, ops[2]);
                if (index_is_id)
                {
                    inherit_expression_dependencies(result_id, ops[3]);
                }
                return true;
            }
            return false;
        }
        {
            switch (unchecked((int)opcode))
            {
                case unchecked((int)Spv.Op.OpFNegate):
                {
                    emit_cooperative_matrix_unary_op(result_type, result_id, ops[2], "-");
                    break;
                }
                case unchecked((int)Spv.Op.OpFAdd):
                {
                    emit_cooperative_matrix_binary_op(result_type, result_id, ops[2], ops[3], "+");
                    break;
                }
                case unchecked((int)Spv.Op.OpFSub):
                {
                    emit_cooperative_matrix_binary_op(result_type, result_id, ops[2], ops[3], "-");
                    break;
                }
                case unchecked((int)Spv.Op.OpFMul):
                case unchecked((int)Spv.Op.OpMatrixTimesScalar):
                {
                    emit_cooperative_matrix_binary_op(result_type, result_id, ops[2], ops[3], "*");
                    break;
                }
                case unchecked((int)Spv.Op.OpFDiv):
                {
                    emit_cooperative_matrix_binary_op(result_type, result_id, ops[2], ops[3], "/");
                    break;
                }
                case unchecked((int)Spv.Op.OpFConvert):
                {
                    {
                        var component_type = type_to_glsl(get__SPIRType(((uint)type.parent_type)), 0u);
                        emit_cooperative_matrix_unary_func_op(result_type, result_id, ops[2], component_type.c_str());
                        break;
                    }
                }
                case unchecked((int)Spv.Op.OpCompositeConstruct):
                {
                    if (instruction.length != 3u)
                    {
                        throw new CompilerError("OpCompositeConstruct for cooperative matrix requires exactly one scalar component.");
                    }
                    emit_cooperative_matrix_unary_op(result_type, result_id, ops[2], "");
                    break;
                }
                case unchecked((int)Spv.Op.OpSelect):
                {
                    emit_cooperative_matrix_select_op(result_type, result_id, ops[2], ops[3], ops[4]);
                    break;
                }
                case unchecked((int)Spv.Op.OpCompositeInsert):
                case unchecked((int)Spv.Op.OpVectorInsertDynamic):
                {
                    {
                        bool index_is_id = unchecked((int)opcode) == unchecked((int)Spv.Op.OpVectorInsertDynamic);
                        uint @object = index_is_id ? ops[3] : ops[2];
                        uint matrix = index_is_id ? ops[2] : ops[3];
                        var index = index_is_id ? to_expression(ops[4], true) : Std.join(ops[4], "u");
                        emit_cooperative_matrix_unary_op(result_type, result_id, matrix, "");
                        statement(to_cooperative_matrix_component(result_id, index), " = ", to_unpacked_expression(@object, true), ";");
                        inherit_expression_dependencies(result_id, @object);
                        if (index_is_id)
                        {
                            inherit_expression_dependencies(result_id, ops[4]);
                        }
                        break;
                    }
                }
                default:
                {
                    throw new CompilerError("Unsupported operation on cooperative matrix in MSL backend.");
                }
            }
        }
        return true;
    }
    public void validate_cooperative_matrix_type(SPIRType type)
    {
        var comp = get__SPIRType(((uint)type.parent_type));
        if (unchecked((int)comp.basetype) != unchecked((int)SPIRType.BaseType.Float) && unchecked((int)comp.basetype) != unchecked((int)SPIRType.BaseType.Half) && unchecked((int)comp.basetype) != unchecked((int)SPIRType.BaseType.BFloat16))
