        }
        if (scope.scalar(0u, 0u) != unchecked((uint)Spv.Scope.ScopeSubgroup))
        {
            throw new CompilerError("MSL cooperative matrices only support Subgroup scope.");
        }
        var rows = get__SPIRConstant(type.ext.cooperative.rows_id);
        var columns = get__SPIRConstant(type.ext.cooperative.columns_id);
        if (rows.specialization || columns.specialization)
        {
            throw new CompilerError("MSL does not support spec-constant dimensions for cooperative matrices.");
        }
        if (rows.scalar(0u, 0u) != 8u || columns.scalar(0u, 0u) != 8u)
        {
            throw new CompilerError("MSL cooperative matrices only support 8x8 dimensions.");
        }
    }
    public void validate_cooperative_matrix_types()
