                    if (unchecked((int)s.min_filter) != unchecked((int)MSLSamplerFilter.MSL_SAMPLER_FILTER_NEAREST))
                    {
                        args.push_back(new CppString("min_filter::linear"));
                    }
                    if (unchecked((int)s.mag_filter) != unchecked((int)MSLSamplerFilter.MSL_SAMPLER_FILTER_NEAREST))
                    {
                        args.push_back(new CppString("mag_filter::linear"));
                    }
