                        case unchecked((int)MSLSamplerMipFilter.MSL_SAMPLER_MIP_FILTER_NONE):
                        {
                            break;
                        }
                        case unchecked((int)MSLSamplerMipFilter.MSL_SAMPLER_MIP_FILTER_NEAREST):
                        {
                            args.push_back(new CppString("mip_filter::nearest"));
                            break;
                        }
                        case unchecked((int)MSLSamplerMipFilter.MSL_SAMPLER_MIP_FILTER_LINEAR):
                        {
                            args.push_back(new CppString("mip_filter::linear"));
