                else
                {
                    if (unchecked((int)s.s_address) != unchecked((int)MSLSamplerAddress.MSL_SAMPLER_ADDRESS_CLAMP_TO_EDGE))
                    {
                        args.push_back(Globals.create_sampler_address("s_", s.s_address));
                    }
                    if (unchecked((int)s.t_address) != unchecked((int)MSLSamplerAddress.MSL_SAMPLER_ADDRESS_CLAMP_TO_EDGE))
                    {
                        args.push_back(Globals.create_sampler_address("t_", s.t_address));
                    }
                    if (unchecked((int)s.r_address) != unchecked((int)MSLSamplerAddress.MSL_SAMPLER_ADDRESS_CLAMP_TO_EDGE))
                    {
